const articles = [];
const liste = document.querySelector("#liste");
function afficher() {
  liste.innerHTML = articles.map(a => `<li>${a}</li>`).join("");
}
document.querySelector("#ajouter").addEventListener("click", () => {
  const champ = document.querySelector("#article");
  if (champ.value.trim()) articles.push(champ.value.trim());
  champ.value = "";
  afficher();
});
